export default class ItemtypeCommentPopover{constructor(e,t=[]){this.container=$(e);this.info_card_selectors=t;this.requests={};this.#e();this.#t()}#e(){this.container.popover({selector:"[data-glpi-popover-source]",container:this.container,html:true,sanitize:false,trigger:"hover",delay:{hide:300},content:e=>{$(".popover").popover("hide");return $(`#${$(e).attr("data-glpi-popover-source")}`).html()}}).on("hide.bs.popover",()=>{for(const e of this.info_card_selectors){if($(`${e}:hover`).length>0){return false}}})}#t(){if(this.info_card_selectors.length===0){return}$(document).on("mouseleave",this.info_card_selectors.join(", "),e=>{const t=$(e.target).closest(".popover");if(t.length===0){return}setTimeout(()=>{const e=$(`[data-glpi-popover-source][aria-describedby="${CSS.escape(t.attr("id"))}"]`);if(e.length>0){const t=bootstrap.Popover.getInstance(e[0]);t.hide()}},300)})}attachTo(e,t,o){const r=`${t}_${o}`;if(!this.requests[r]){const e=`comment_popover_${t}_${o}_${Math.floor(Math.random()*1e6)}`;this.requests[r]=$.ajax({url:`${CFG_GLPI.root_doc}/ajax/comments.php`,type:"POST",data:{itemtype:t,value:o}}).then(t=>{if(t){$(document.body).append(`<div id="${e}" style="display: none;">${t}</div>`);return e}return null})}this.requests[r].then(t=>{if(t){$(e).attr("data-glpi-popover-source",t)}})}}